export const VERSION='1.0.0';
export const STORAGE_KEY='qf-studio-chapter-06-v1';
function nums(x,min=1){if(!Array.isArray(x)||x.length<min||x.some(v=>typeof v!=='number'||!Number.isFinite(v)))throw Error('Supply finite numeric observations.');return x;}
export function mean(x){nums(x);return x.reduce((a,b)=>a+b,0)/x.length;}
export function sampleSD(x){nums(x,2);if(x.every(v=>v===x[0]))return 0;const m=mean(x);return Math.sqrt(x.reduce((s,v)=>s+(v-m)**2,0)/(x.length-1));}
export function wealth(x,start=100){nums(x);if(x.some(v=>v<=-100)||!Number.isFinite(start)||start<=0)throw Error('Use a positive initial value and returns above −100%.');let w=start;return [w,...x.map(v=>(w*=1+v/100))];}
const q=(id,title,answer,hint,critical=false,type='number')=>({id,title,answer,hint,critical,type,tolerance:.011});

export const STEPS=[['start','Set up a portfolio comparison',10],['weights','Weight the same-date returns',25],['diversification','Inspect concentration',25],['rebalance','Separate two policies',25],['beta','Read benchmark sensitivity',25],['lab','Change the allocation',40],['assessment','Independent transfer',20],['finish','Save a portfolio card',10]];
export const DATA=[{date:'2025-01',a:10,b:-5,market:4},{date:'2025-02',a:-10,b:5,market:-3},{date:'2025-03',a:8,b:0,market:3},{date:'2025-04',a:-4,b:2,market:-1},{date:'2025-05',a:6,b:-2,market:2},{date:'2025-06',a:0,b:3,market:1}];
export const A=DATA.map(r=>r.a),B=DATA.map(r=>r.b);
export function weighted(a,b,w){if(typeof w!=='number'||!Number.isFinite(w)||w<0||w>1||!Number.isFinite(a)||!Number.isFinite(b))throw Error('Use finite returns and A weight 0–1.');return w*a+(1-w)*b;}
export function aligned(left,right){if(!Array.isArray(left)||!Array.isArray(right)||left.length!==right.length||left.length<2||new Set(left.map(r=>r.date)).size!==left.length||left.some((r,i)=>typeof r.date!=='string'||r.date!==right[i].date||!Number.isFinite(r.value)||!Number.isFinite(right[i].value)))throw Error('Use at least two unique matching dates in the same order.');return [left.map(r=>r.value),right.map(r=>r.value)];}
export function sensitivity(x,m){nums(x,2);nums(m,2);if(x.length!==m.length)throw Error('Align matching benchmark dates.');const mx=mean(x),mm=mean(m),xx=x.every(v=>v===x[0])?0:x.reduce((s,v)=>s+(v-mx)**2,0),mm2=m.every(v=>v===m[0])?0:m.reduce((s,v)=>s+(v-mm)**2,0),cross=x.reduce((s,v,i)=>s+(v-mx)*(m[i]-mm),0);return {correlation:xx===0||mm2===0?null:cross/Math.sqrt(xx*mm2),beta:mm2===0?null:cross/mm2};}
export function portfolio(w){if(typeof w!=='number'||!Number.isFinite(w)||w<0||w>1)throw Error('Use a starting A weight 0–1.');let a=100*w,b=100*(1-w),mix=100;const rows=[{date:'Initial',mix:100,buyHold:100,weightA:w,mixReturn:0}];for(const r of DATA){const mr=weighted(r.a,r.b,w);mix*=1+mr/100;a*=1+r.a/100;b*=1+r.b/100;rows.push({date:r.date,mix,buyHold:a+b,weightA:a/(a+b),mixReturn:mr});}return rows;}
export const DEFAULT_PARAMETER=50;
export function experiment(parameter=50){if(typeof parameter!=='number'||!Number.isFinite(parameter)||parameter<0||parameter>100)throw Error('Use A allocation 0–100%.');const w=parameter/100,rows=portfolio(w),returns=DATA.map(r=>weighted(r.a,r.b,w));return {parameter,rows,hand:returns[0],sd:sampleSD(returns),...sensitivity(returns,DATA.map(r=>r.market))};}
export const PRACTICE={weights:[q('w1','A returns 10%, B −5%; starting weights A60%, B40%. Portfolio monthly return (%)?',4,'0.6×10+0.4×(−5)=4%. Weights are fractions that sum to one.'),q('w2','New case A −4%, B 2%, weights A25%, B75%. Portfolio return (%)?',.5,'0.25×(−4)+0.75×2=.5%. Use same-date total returns.')],diversification:[q('c1','For A80%, B20%, concentration H=wA²+wB² (0–1)?',.68,'.8²+.2²=.68. This is an allocation concentration index, not a complete risk measure.'),q('c2','If the two assets always have identical returns, enter 1 if splitting weights alone lowers their return SD; 2 if it does not.',2,'Weighted identical return paths remain the same path. Two names do not guarantee diversification.',true,'choice')],rebalance:[q('r1','Start 100 split 50/50; A +20%, B 0%. Buy-and-hold A weight after that month (fraction 0–1)?',60/110,'A grows to60, B stays50; A weight=60/110, not .5.'),q('r2','New two-month case A +20%, then −20%; B 0%,0%. Monthly constant-mix 50/50 ending wealth from100?',99,'Rebalanced portfolio returns +10%,−10%:100×1.1×.9=99. Buy-and-hold ends98.')],beta:[q('t1','Aligned benchmark [−1,0,1]%, portfolio [−2,0,2]%. Sample beta?',2,'Beta=cov(portfolio,benchmark)/var(benchmark). Cross-sum4 / benchmark squared sum2 =2.'),q('t2','A constant benchmark makes benchmark variance zero. Enter 1 for beta=0; 2 for undefined.',2,'A zero denominator cannot estimate a beta.',true,'choice')]};
export const ASSESSMENTS=[q('a1','A +8%, B −2%, weights A30%, B70%. Monthly portfolio return (%)?',1,'0.3×8+0.7×(−2)=1.'),q('a2','A70%, B30%. Concentration H=wA²+wB² (fraction)?',.58,'.49+.09=.58.'),q('a3','Enter 1 to pair same-date monthly total returns before weighting; 2 to pair independently sorted returns.',1,'Preserve matching dates and basis; independent sorting creates false pairs.',true,'choice'),q('a4','Start100 split50/50; A −20%, B +20%. Buy-and-hold A weight after one month (fraction)?',.4,'A40, B60, total100; weight .4.'),q('a5','Same inputs, next month A +20%, B −20%. Buy-and-hold final wealth?',96,'A40×1.2=48; B60×.8=48; total96. Constant-mix would remain100.'),q('a6','Benchmark [−2,0,2]%, portfolio [−1,0,1]%. Sample beta?',.5,'Cross-sum4 / benchmark squared sum8 = .5.'),q('a7','If benchmark variance is zero, enter 1 for undefined beta; 2 for zero beta.',1,'The denominator is zero, so report undefined.',true,'choice'),q('a8','Enter 1 if this cost-free tiny sample proves rebalancing wins; 2 if policy comparison is sample- and cost-conditional.',2,'Rebalancing costs are omitted and other paths can reverse the comparison.',true,'choice')];

export function check(q,raw){if(typeof raw==='boolean'||raw===null||String(raw??'').trim()==='')return false;const n=Number(raw);return Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.type==='choice'?0:q.tolerance);}
export function grade(answers){const details=ASSESSMENTS.map(q=>({id:q.id,correct:check(q,answers[q.id]),critical:q.critical}));const score=details.filter(d=>d.correct).length;return {score,passed:score>=7&&details.filter(d=>d.critical).every(d=>d.correct),details};}
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],runs:[],attempts:[]});
export function invalidate(s,id){for(const [step,qs]of Object.entries(PRACTICE))if(qs.some(q=>q.id===id)||id===step+'Reflection'||id===step+'Criteria'){delete s.done[step];delete s.checked[id];}if(id.startsWith('quiz-')||id==='revision'){delete s.done.assessment;s.fields.quizDirty='yes';}if(['prediction','parameter','hand','labReflection','labCriteria'].includes(id)){delete s.done.lab;if(id==='hand')s.fields.handVerified='';}if(id.startsWith('card'))delete s.done.finish;if(id==='setup')delete s.done.start;}
export function labEvidence(s){const run=s.runs.at(-1);return !!run&&(s.fields.parameter===undefined||s.fields.parameter.trim()!=='')&&run.prediction===s.fields.prediction&&run.parameter===Number(s.fields.parameter??DEFAULT_PARAMETER)&&new Set(s.runs.map(r=>r.parameter)).size>=2&&check({answer:run.hand,tolerance:.011},s.fields.hand)&&s.fields.handVerified==='yes'&&(s.fields.labReflection||'').trim().length>=50&&s.fields.labCriteria==='yes';}
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s?.version!==VERSION||!record(s.fields)||Object.values(s.fields).some(v=>typeof v!=='string')||!record(s.done)||!record(s.checked)||Object.values(s.done).some(v=>typeof v!=='boolean')||Object.values(s.checked).some(v=>typeof v!=='boolean')||!Array.isArray(s.runs)||!Array.isArray(s.attempts))throw Error();const restored={...freshState(),fields:s.fields,practiceAttempts:(Array.isArray(s.practiceAttempts)?s.practiceAttempts:[]).filter(a=>record(a)&&typeof a.id==='string'&&typeof a.raw==='string'&&typeof a.correct==='boolean'&&typeof a.time==='string'),runs:s.runs.map(r=>{if(typeof r.prediction!=='string'||typeof r.time!=='string')throw Error();return {...experiment(r.parameter),prediction:r.prediction,time:r.time};}),attempts:s.attempts.map(a=>{if(!record(a.answers)||Object.values(a.answers).some(v=>typeof v!=='string')||typeof a.time!=='string'||(a.revision!==undefined&&typeof a.revision!=='string'))throw Error();return {...a,...grade(a.answers)};})};for(const[step,qs]of Object.entries(PRACTICE)){for(const q of qs)if(s.checked[q.id]===true&&check(q,s.fields[q.id]))restored.checked[q.id]=true;if(qs.every(q=>restored.checked[q.id])&&(s.fields[step+'Reflection']||'').trim().length>=30&&s.fields[step+'Criteria']==='yes')restored.done[step]=true;}if(s.fields.setup==='yes')restored.done.start=true;const latest=restored.attempts.at(-1);if(latest?.passed&&s.fields.quizDirty!=='yes'&&latest.revision?.length>=30&&ASSESSMENTS.every(q=>latest.answers[q.id]===s.fields['quiz-'+q.id]))restored.done.assessment=true;if(['cardMethod','cardCheck','cardLimit'].every(k=>(s.fields[k]||'').trim().length>=30)&&s.fields.cardCriteria==='yes')restored.done.finish=true;if(labEvidence(restored))restored.done.lab=true;return restored;}catch{return freshState();}}
